+          </span>
+          <span>little library</span>
+        </a>
+        <div class=\"topbar-note\"><span class=\"status-dot\"></span> A home for your reading life</div>
+      </header>
+      <main id=\"app\" class=\"main-content\" aria-live=\"polite\">
+        <div class=\"loading-state\">Opening your library<span class=\"loading-dots\">…</span></div>
+      </main>
