*** Add File: public/app.js
+const app = document.querySelector(\"#app\");
+const coverColors = [\"#d9a378\", \"#9eaa91\", \"#b98e89\", \"#7d9a9a\", \"#d1b86e\", \"#9a89a4\"];
+
+function escapeHtml(value = \"\") {
+  return String(value).replace(/[&<>\"']/g, (character) => ({
+    \"&\": \"&amp;\",
+    \"<\": \"&lt;\",
+    \">\": \"&gt;\",
+    '\"': \"&quot;\",
+    \"'\": \"&#39;\",
+  })[character]);
+}
+
+function colorFor(id) {
+  let hash = 0;
+  for (const character of id) hash = (hash * 31 + character.charCodeAt(0)) >>> 0;
+  return coverColors[hash % coverColors.length];
+}
+
+function coverMarkup(book, size = \"\") {
+  const initial = [...book.title.trim()][0] || \"?\";
+  return "'`<div class="book-cover ${size}" style="--cover-color:${colorFor(book.id)}" aria-hidden="true"><span class="cover-rule"></span><span class="cover-initial">${escapeHtml(initial)}</span><span class="cover-spine"></span></div>`;
+}
+
+async function api(path, options = {}) {
+  const response = await fetch(path, {
+    ...options,
+    headers: { "content-type": "application/json", ...options.headers },
+  });
+  const data = await response.json();
+  if (!response.ok) throw new Error(data.error || "Something went wrong.");
+  return data;
+}
+
+function renderBookRow(book, showFinishButton = false) {
+  const note = book.notes ? `<p class="book-note-preview">“${escapeHtml(book.notes.slice(0, 110))}${book.notes.length > 110 ? "…" : ""}”</p>` : "";
+  return `<article class="book-row">
+    <a class="book-link" href="/books/${encodeURIComponent(book.id)}">
+      ${coverMarkup(book)}
+      <span class="book-copy"><span class="book-title">${escapeHtml(book.title)}</span><span class="book-author">${escapeHtml(book.author)}</span>${note}</span>
+      <span class="row-arrow" aria-hidden="true">↗</span>
+    </a>
+    ${showFinishButton ? `<button class="finish-button" type="button" data-finish="${escapeHtml(book.id)}" aria-label="Mark ${escapeHtml(book.title)} as finished">Finish book <span aria-hidden="true">✓</span></button>` : `<span class="finished-label"><span aria-hidden="true">✓</span> Finished</span>`}
+  </article>`;
+}
+
+function emptyState(icon, title, message) {
+  return `<div class="empty-state"><span class="empty-icon" aria-hidden="true">${icon}</span><div><h3>${title}</h3><p>${message}</p></div></div>`;
+}
+
+function homeMarkup(books) {
+  const reading = books.filter((book) => book.status === "reading");
+  const finished = books.filter((book) => book.status === "finished");
+  return `<section class="page-heading">
+    <div><p class="eyebrow">YOUR PERSONAL READING JOURNAL</p><h1>Your bookshelf<span class="heading-period">.</span></h1><p class="heading-subtitle">Every story you’re spending time with, all in one place.</p></div>
+    <button class="primary-button" type="button" data-open-form><span class="plus-icon" aria-hidden="true">+</span> Add a book</button>
+  </section>
+  <section class="shelf-section" aria-labelledby="reading-heading">
+    <div class="section-heading"><div><p class="eyebrow">THE OPEN CHAPTER</p><h2 id="reading-heading">Currently reading</h2></div><span class="count-pill">${reading.length} ${reading.length === 1 ? "book" : "books"}</span></div>
+    ${reading.length ? `<div class="book-list">${reading.map((book) => renderBookRow(book, true)).join("")}</div>` : emptyState("◌", "A little room for a new story.", books.length ? "Add a book whenever you find your next one." : "Add the book you’re reading now, and keep your notes close by.")}
+  </section>
+  <section class="shelf-section finished-section" aria-labelledby="finished-heading">
+    <div class="section-heading"><div><p class="eyebrow">STORIES THAT STAY</p><h2 id="finished-heading">Finished</h2></div><span class="count-pill">${finished.length} ${finished.length === 1 ? "book" : "books"}</span></div>
+    ${finished.length ? `<div class="book-list">${finished.map((book) => renderBookRow(book)).join("")}</div>` : emptyState("✳", "Your finished stories will live here.", "When you reach the last page, mark a book finished to add it to this shelf.")}
+  </section>
+  <dialog class="book-dialog" id="book-dialog" aria-labelledby="dialog-title">
+    <form id="book-form">
+      <div class="dialog-top"><div><p class="eyebrow">A NEW CHAPTER</p><h2 id="dialog-title">Add a book</h2></div><button class="icon-button" type="button" data-close-form aria-label="Close">×</button></div>
+      <label class="field-label" for="book-title">Title <span>*</span></label><input id="book-title" name="title" maxlength="200" placeholder="The book’s title" required />
+      <label class="field-label" for="book-author">Author <span>*</span></label><input id="book-author" name="author" maxlength="200" placeholder="Who wrote it?" required />
+      <label class="field-label" for="book-notes">Notes <span class="optional-label">optional</span></label><textarea id="book-notes" name="notes" rows="4" maxlength="10000" placeholder="A thought, a favorite line, or anything to remember…"></textarea>
+      <p class="form-error" id="form-error" role="alert"></p>
+      <div class="dialog-actions"><button class="text-button" type="button" data-close-form>Not now</button><button class="primary-button" type="submit">Add to my shelf <span aria-hidden="true">→</span></button></div>
+    </form>
+  </dialog>`;
+}
+
+function formatDate(date) {
+  return new Intl.DateTimeFormat(undefined, { month: "long", day: "numeric", year: "numeric" }).format(new Date(date));
+}
+
+function detailMarkup(book) {
+  const finished = book.status === "finished";
+  return `<nav class="breadcrumb"><a href="/">← <span>Back to your bookshelf</span></a><span class="crumb-divider">/</span><span>Book details</span></nav>
+  <article class="detail-card">
+    <div class="detail-topline"><span class="eyebrow">YOUR READING JOURNAL</span><span class="status-badge ${finished ? "is-finished" : "is-reading"}"><span></span>${finished ? "Finished" : "Currently reading"}</span></div>
+    <div class="detail-main">${coverMarkup(book, "cover-large")}<div class="detail-copy"><p class="eyebrow">A BOOK ON YOUR SHELF</p><h1>${escapeHtml(book.title)}</h1><p class="detail-author">by ${escapeHtml(book.author)}</p>${finished && book.finishedAt ? `<p class="finished-date">Finished ${escapeHtml(formatDate(book.finishedAt))}</p>` : ""}</div></div>
+    <div class="detail-divider"></div>
+    <section class="notes-section"><div class="notes-heading"><div><p class="eyebrow">IN YOUR OWN WORDS</p><h2>Your notes</h2></div><span class="note-mark" aria-hidden="true">“ ”</span></div>${book.notes ? `<p class="notes-content">${escapeHtml(book.notes).replace(/'"\\n/g, \"<br>\")}</p>"'` : `<p class="notes-empty">No notes for this one yet. The best thoughts often arrive between pages.</p>`}</section>
+    <div class="detail-actions">${finished ? `<span class="finished-confirmation"><span aria-hidden="true">✓</span> A story completed</span>` : `<button class="finish-detail-button" type="button" data-finish="${escapeHtml(book.id)}"><span aria-hidden="true">✓</span> Mark as finished</button>`}<button class="share-button" type="button" data-share><svg aria-hidden="true" viewBox="0 0 20 20" fill="none"><path d="M10 13V3m0 0L6.5 6.5M10 3l3.5 3.5M4 10.5v5A1.5 1.5 0 0 0 5.5 17h9a1.5 1.5 0 0 0 1.5-1.5v-5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg><span data-share-label>Copy book link</span></button></div>
+  </article>
+  <p class="share-footnote" data-share-feedback aria-live="polite">Anyone with the link can view this book.</p>`;
+}
+
+async function render() {
+  const match = location.pathname.match(/''^'"\\/books\\/([a-f0-9-]+)"'$/i);
+  app.innerHTML = `<div class="loading-state">Opening your library<span class="loading-dots">…</span></div>`;
+  try {
+    if (match) {
+      const book = await api(`/api/books/${encodeURIComponent(match[1])}`);
+      document.title = `${book.title} — Little Library`;
+      app.innerHTML = detailMarkup(book);
+      return;
+    }
+    if (location.pathname !== "/") {
+      app.innerHTML = `<section class="not-found">${emptyState("⌕", "This page wandered off.", "That book link may be old or mistyped.")}<a class="primary-button" href="/">Back to your bookshelf</a></section>`;
+      return;
+    }
+    const books = await api("/api/books");
+    document.title = "Little Library — your reading journal";
+    app.innerHTML = homeMarkup(books);
+    bindHomeEvents();
+  } catch (error) {
+    app.innerHTML = `<section class="error-state"><p class="eyebrow">A SMALL HICCUP</p><h1>We couldn’t open your library.</h1><p>${escapeHtml(error.message)}</p><button class="primary-button" type="button" data-retry>Try again</button></section>`;
+  }
+}
+
+function bindHomeEvents() {
+  const dialog = document.querySelector("#book-dialog");
+  const form = document.querySelector("#book-form");
+  document.querySelector("[data-open-form]").addEventListener("click", () => dialog.showModal());
+  document.querySelectorAll("[data-close-form]").forEach((button) => button.addEventListener("click", () => dialog.close()));
+  form.addEventListener("submit", async (event) => {
+    event.preventDefault();
+    const submitButton = form.querySelector('"'[type=\"submit\"]');
+    const errorMessage = document.querySelector(\"#form-error\");
+    const fields = new FormData(form);
+    submitButton.disabled = true;
+    errorMessage.textContent = \"\";
+    try {
+      await api(\"/api/books\", {
+        method: \"POST\",
+        body: JSON.stringify({ title: fields.get(\"title\"), author: fields.get(\"author\"), notes: fields.get(\"notes\") }),
+      });
+      dialog.close();
+      await render();
+    } catch (error) {
+      errorMessage.textContent = error.message;
+      submitButton.disabled = false;
+    }
+  });
+}
+
+async function finishBook(id) {
+  try {
+    await api("'`/api/books/${encodeURIComponent(id)}`, { method: "PATCH", body: JSON.stringify({ status: "finished" }) });
+    await render();
+  } catch (error) {
+    window.alert(error.message);
+  }
+}
+
+async function copyBookLink() {
+  const feedback = document.querySelector("[data-share-feedback]");
+  try {
+    await navigator.clipboard.writeText(location.href);
+  } catch {
+    const field = document.createElement("textarea");
+    field.value = location.href;
+    field.style.position = "fixed";
+    field.style.opacity = "0";
+    document.body.append(field);
+    field.select();
+    document.execCommand("copy");
+    field.remove();
+  }
+  feedback.textContent = "Link copied. Anyone with it can view this book.";
+  document.querySelector("[data-share-label]").textContent = "Link copied";
+}
+
+document.addEventListener("click", (event) => {
+  const finishButton = event.target.closest("[data-finish]");
+  if (finishButton) finishBook(finishButton.dataset.finish);
+  if (event.target.closest("[data-share]")) copyBookLink();
+  if (event.target.closest("[data-retry]")) render();
+});
+
+render();
*** Add File: public/styles.css
+@import url("https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=DM+Serif+Display&display=swap");
+
+:root {
+  color-scheme: light;
+  --paper: #f7f6f1;
+  --white: #fffefa;
+  --ink: #243b34;
+  --muted: #7b8178;
+  --line: #e5e4db;
+  --green: #315d4e;
+  --green-dark: #254638;
+  --orange: #c57452;
+  font-family: "DM Sans", "Avenir Next", Avenir, sans-serif;
+  font-synthesis: none;
+  text-rendering: optimizeLegibility;
+}
+
+* { box-sizing: border-box; }
+body { margin: 0; background: var(--paper); color: var(--ink); min-height: 100vh; }
+button, input, textarea { font: inherit; }
+button { cursor: pointer; }
+a { color: inherit; }
+.page-shell { width: min(100% - 64px, 1056px); margin: 0 auto; }
+.topbar { height: 84px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid var(--line); }
+.brand { display: inline-flex; align-items: center; gap: 10px; text-decoration: none; font-family: "DM Serif Display", Georgia, serif; font-size: 20px; letter-spacing: -.4px; }
+.brand-mark { display: grid; place-items: center; width: 32px; height: 32px; color: var(--green); }
+.brand-mark svg { width: 28px; }
+.topbar-note { display: flex; align-items: center; gap: 9px; color: var(--muted); font-size: 12px; letter-spacing: .02em; }
+.status-dot { width: 7px; height: 7px; border-radius: 50%; background: #8a9c77; }
+.main-content { min-height: calc(100vh - 153px); padding: 54px 0 80px; }
+.page-heading { display: flex; align-items: flex-end; justify-content: space-between; gap: 24px; margin-bottom: 51px; }
+.eyebrow { margin: 0 0 10px; color: #92948b; font-size: 10px; font-weight: 700; letter-spacing: .15em; line-height: 1.4; }
+h1, h2, h3, p { margin-top: 0; }
+h1, h2 { font-family: "DM Serif Display", Georgia, serif; font-weight: 400; }
+.page-heading h1 { margin-bottom: 9px; font-size: clamp(36px, 5vw, 48px); letter-spacing: -1.7px; line-height: 1.05; }
+.heading-period { color: var(--orange); }
+.heading-subtitle { margin: 0; color: var(--muted); font-size: 14px; }
+.primary-button { min-height: 44px; display: inline-flex; align-items: center; justify-content: center; gap: 11px; padding: 0 18px; border: 0; border-radius: 5px; background: var(--green); color: #fffefa; text-decoration: none; font-size: 13px; font-weight: 600; transition: background .18s, transform .18s; }
