+const app = document.querySelector(\"#app\");
+const coverColors = [\"#d9a378\", \"#9eaa91\", \"#b98e89\", \"#7d9a9a\", \"#d1b86e\", \"#9a89a4\"];
+
+function escapeHtml(value = \"\") {
+  return String(value).replace(/[&<>\"']/g, (character) => ({
+    \"&\": \"&amp;\",
+    \"<\": \"&lt;\",
+    \">\": \"&gt;\",
+    '\"': \"&quot;\",
+    \"'\": \"&#39;\",
+  })[character]);
+}
+
+function colorFor(id) {
+  let hash = 0;
+  for (const character of id) hash = (hash * 31 + character.charCodeAt(0)) >>> 0;
+  return coverColors[hash % coverColors.length];
+}
+
+function coverMarkup(book, size = \"\") {
+  const initial = [...book.title.trim()][0] || \"?\";
+  return "'`<div class="book-cover ${size}" style="--cover-color:${colorFor(book.id)}" aria-hidden="true"><span class="cover-rule"></span><span class="cover-initial">${escapeHtml(initial)}</span><span class="cover-spine"></span></div>`;
+}
